// node --test test/   (Node 20+: global crypto.subtle, atob, Response)
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { verify } from '../src/token.js';
import worker from '../src/index.js';

// Shared with tests/Unit/VideoTokenTest.php — generated by Laravel's VideoToken.
const SECRET = 'soaar-shared-test-vector-secret';
const TOKEN =
  'eyJ1Ijo0MiwidiI6Nywic2lkIjoiOWYxYzJlNGEtNWI2ZC00ZTdmLThhOWItMGMxZDJlM2Y0YTViIiwiZXhwIjoxODkzNDU2MDAwfQ' +
  '.JfBW5m8hWckZOFrAK1MN--KDnv19w58tWMBdOkp4vEU';

const env = {
  VIDEO_TOKEN_SECRET: SECRET,
  KEY_BASE: 'https://api.soaar.tech/api/videos',
  ALLOWED_ORIGINS: 'https://dash.example',
  BUCKET: {
    async get(key) {
      const files = {
        'hls/7/master.m3u8': '#EXTM3U\nv0/index.m3u8\n',
        'hls/7/v0/index.m3u8': '#EXTM3U\n#EXT-X-KEY:METHOD=AES-128,URI="__KEY_URI__",IV=0x00\nseg_0000.ts\n',
        'hls/7/v0/seg_0000.ts': 'TS',
      };
      if (!(key in files)) return null;
      return { text: async () => files[key], body: files[key] };
    },
  },
};

const get = (path, headers = {}) => worker.fetch(new Request(`https://media.soaar.tech${path}`, { headers }), env);

test('the Laravel test vector verifies', async () => {
  assert.deepEqual(await verify(TOKEN, SECRET), {
    u: 42,
    v: 7,
    sid: '9f1c2e4a-5b6d-4e7f-8a9b-0c1d2e3f4a5b',
    exp: 1893456000,
  });
});

test('wrong secret, tampered payload or signature fail', async () => {
  const [payload, sig] = TOKEN.split('.');
  assert.equal(await verify(TOKEN, 'other-secret'), null);
  assert.equal(await verify(`${payload}x.${sig}`, SECRET), null);
  assert.equal(await verify(`${payload}.${sig.slice(0, -2)}AA`, SECRET), null);
  assert.equal(await verify('garbage', SECRET), null);
});

test('playlists get the key URI written in', async () => {
  const res = await get(`/p/${TOKEN}/hls/7/v0/index.m3u8`);
  assert.equal(res.status, 200);
  assert.equal(res.headers.get('Content-Type'), 'application/vnd.apple.mpegurl');
  const body = await res.text();
  assert.ok(body.includes(`URI="https://api.soaar.tech/api/videos/7/key?t=${TOKEN}"`));
  assert.ok(!body.includes('__KEY_URI__'));
});

test('segments are served as video/mp2t, CORS only for allowed origins', async () => {
  const ok = await get(`/p/${TOKEN}/hls/7/v0/seg_0000.ts`, { Origin: 'https://dash.example' });
  assert.equal(ok.status, 200);
  assert.equal(ok.headers.get('Content-Type'), 'video/mp2t');
  assert.equal(ok.headers.get('Access-Control-Allow-Origin'), 'https://dash.example');

  const other = await get(`/p/${TOKEN}/hls/7/v0/seg_0000.ts`, { Origin: 'https://evil.example' });
  assert.equal(other.headers.get('Access-Control-Allow-Origin'), null);
});

test('no token, wrong video, tampered token or path traversal are refused', async () => {
  assert.equal((await get('/hls/7/master.m3u8')).status, 404);
  assert.equal((await get(`/p/${TOKEN}/hls/8/master.m3u8`)).status, 403);
  assert.equal((await get(`/p/${TOKEN.slice(0, -1)}A/hls/7/master.m3u8`)).status, 403);
  // URL parsing resolves the .. first, which lands on video 8: still refused.
  assert.ok([403, 404].includes((await get(`/p/${TOKEN}/hls/7/../8/master.m3u8`)).status));
  assert.equal((await get(`/p/${TOKEN}/hls/7/v0/%2e%2e/secret.ts`)).status, 404);
});
